create table public.stai_site_content (
  id text primary key check (id = 'main'),
  content jsonb not null check (jsonb_typeof(content) = 'object'),
  published boolean not null default false,
  updated_at timestamptz not null default now()
);
alter table public.stai_site_content enable row level security;
revoke all on public.stai_site_content from public, anon, authenticated;
grant select on public.stai_site_content to anon, authenticated;
grant all on public.stai_site_content to service_role;
create policy "Read published STAI website content" on public.stai_site_content
  for select to anon, authenticated
  using (published = true and id = 'main');
comment on table public.stai_site_content is 'Public STAI Lab website content. Dashboard editors maintain the main JSON document; website visitors have read-only access.';
insert into public.stai_site_content (id, content, published)
values ('main', $stai_content${"site":{"name":"Safe and Trusted AI Lab","line":"Department of Computer Science & Information Systems · BITS Pilani, Pilani Campus"},"nav":[{"id":"home","label":"Home"},{"id":"about","label":"About"},{"id":"research","label":"Research"},{"id":"team","label":"Team"},{"id":"news","label":"News"},{"id":"contact","label":"Contact"}],"footer":["Safe and Trusted AI Lab · CSIS · BITS Pilani, Pilani Campus","Pilani · Rajasthan 333031 · India"],"home":{"title":"Safe and Trusted AI Lab","lead":"We study how people understand, rely on, evaluate, and govern artificial intelligence in consequential settings.","note":"Our work connects human-AI interaction, safety, auditing, and governance, with particular attention to public-sector systems and the realities of emerging economies."},"about":{"title":"Trust must be earned","lead":"The STAI Lab investigates when people should rely on AI, when they should question it, and how institutions can make that distinction visible.","body":["We approach AI as a socio-technical system. Model behaviour matters, but so do interfaces, organizational incentives, policy choices, deployment conditions, and the people affected by automated decisions.","Our work combines controlled studies, interviews, systematic reviews, safety analysis, and audits of real-world systems. We aim to turn broad principles such as transparency, accountability, and appropriate reliance into methods that can be tested and used."],"contextLabel":"Institutional context","contextBody":"The lab is based in the Department of Computer Science & Information Systems at BITS Pilani, Pilani Campus. Students engage through departmental courses, projects, research programmes, and announced lab opportunities."},"thrusts":[{"title":"Appropriate reliance in human-AI decisions","method":"Experiments · interface studies · interviews","line":"Designing decision support that helps people rely on AI in proportion to its actual reliability.","para":"High trust is not always good trust. We study how explanations, uncertainty displays, interaction design, and deliberation affect whether people accept, reject, or verify automated advice. The goal is calibrated reliance rather than persuasion."},{"title":"Safety assessment for public-sector AI","method":"Socio-technical analysis · STPA · evaluation","line":"Translating safety principles into practical assessment methods for public services and administration.","para":"Public-sector AI can influence access to services, welfare, and administrative decisions. We examine system-level hazards, oversight gaps, and failure pathways so that safety evaluation covers institutions and workflows, not only model accuracy."},{"title":"Auditing and red-teaming","method":"Field audit · adversarial evaluation · documentation review","line":"Testing deployed AI systems against realistic misuse, failure, and accountability scenarios.","para":"We develop audit and red-team approaches suited to systems with limited documentation, multilingual use, and uneven access to technical evidence. The work asks what can be measured from outside a system and what responsible internal access should enable."},{"title":"AI governance and assurance","method":"Policy analysis · stakeholder research · comparative review","line":"Studying how audits, certification, insurance, and governance can support trustworthy deployment.","para":"We investigate how assurance mechanisms shape behaviour before and after deployment. A particular focus is whether tools such as certification, independent auditing, and insurance can create credible incentives for safer and more accountable AI systems."}],"pubNotice":"Verified lab publications will be added here as they are released. We do not list provisional or unconfirmed work.","publications":[],"people":{"pi":{"name":"Prof. Siddharth Mehrotra","role":"Principal Investigator · Assistant Professor, CSIS","affiliations":"BITS Pilani, Pilani Campus","supervisionNote":"Research interests include appropriate trust in human-AI interaction, public-sector AI safety, algorithmic auditing, and trustworthy AI governance.","portraitSlot":{"label":"Principal investigator portrait"},"links":[{"label":"Email","value":"siddharth.mehrotra@pilani.bits-pilani.ac.in","href":"mailto:siddharth.mehrotra@pilani.bits-pilani.ac.in"},{"label":"Homepage","value":"siddharthmehrotra.com","href":"https://www.siddharthmehrotra.com"}]},"students":[],"network":[]},"team":{"studentsNotice":"Student profiles and current projects will be published after the lab roster is confirmed."},"news":[{"date":"19 Sep 2026","title":"Safe and Trusted AI Lab inauguration","body":"The lab will be formally inaugurated at BITS Pilani, Pilani Campus, with invited talks and a discussion on building AI systems that deserve public trust."},{"date":"Mar 2026","title":"STAI Lab established at BITS Pilani","body":"The Safe and Trusted AI Lab begins its work in the Department of Computer Science & Information Systems, connecting human-AI interaction, safety, auditing, and governance."}],"contact":{"address":["Safe and Trusted AI Lab","Department of Computer Science & Information Systems","BITS Pilani, Pilani Campus","Pilani, Rajasthan 333031, India"],"directions":"For visits, collaborations, and research enquiries, contact the lab by email before arriving on campus.","photoSlot":{"label":"Lab photograph"}}}$stai_content$::jsonb, true);
